// Clean-room TSVC s232 profile; see package rights note.
fn put64(out:[*]u8,p:usize,v:i64)void{const bits=@as(u64,@bitCast(v));for(0..8)|k|out[p+k]=@truncate(bits>>(8*k));}
pub export fn tsvc_s232_triangular_row_square_recurrence(input:?[*]const i64,length:usize,output:?[*]u8,capacity:usize)i64{if(input==null or length<9 or length>51)return -1;const v=input.?[0..length];const nr=v[0];if(nr<2 or nr>5)return -1;const n:usize=@intCast(nr);const nn=n*n;if(length!=1+2*nn)return -1;var a=[_]i64{0}**25;var b=[_]i64{0}**25;for(0..nn)|i|{if(v[1+i]< -1 or v[1+i]>1 or v[1+nn+i]< -1 or v[1+nn+i]>1)return -1;a[i]=v[1+i];b[i]=v[1+nn+i];}if(output==null or capacity<8*nn)return -2;for(1..n)|j|{for(1..j+1)|i|{const x=a[j*n+i-1];a[j*n+i]=x*x+b[j*n+i];}}for(0..nn)|i|put64(output.?,8*i,a[i]);return @intCast(nn);}
